//! Trading signal definitions and utilities
//!
//! This module defines the core signal types that strategies generate to indicate
//! trading decisions. Signals contain information about when, what, and how to trade.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use bigdecimal::BigDecimal;

/// A trading signal generated by a strategy
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Signal {
    /// Unique identifier for this signal
    pub id: String,
    /// Timestamp when the signal was generated
    pub timestamp: DateTime<Utc>,
    /// Type of signal (Buy, Sell, Hold, etc.)
    pub signal_type: SignalType,
    /// Strength/confidence of the signal
    pub strength: SignalStrength,
    /// Suggested price for the signal (optional)
    pub price: Option<BigDecimal>,
    /// Suggested quantity for the signal (optional)
    pub quantity: Option<BigDecimal>,
    /// Reason for generating this signal
    pub reason: SignalReason,
    /// Additional metadata for the signal
    pub metadata: HashMap<String, SignalMetadata>,
}

/// Types of trading signals
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum SignalType {
    /// Buy signal - enter a long position
    Buy,
    /// Sell signal - enter a short position or close long position
    Sell,
    /// Hold signal - maintain current position
    Hold,
    /// Close signal - close current position regardless of direction
    Close,
    /// Scale in - add to existing position
    ScaleIn,
    /// Scale out - reduce existing position
    ScaleOut,
    /// Stop loss signal
    StopLoss,
    /// Take profit signal
    TakeProfit,
    /// Custom signal type
    Custom(String),
}

/// Signal strength/confidence levels
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum SignalStrength {
    /// Weak signal - low confidence
    Weak,
    /// Medium signal - moderate confidence
    Medium,
    /// Strong signal - high confidence
    Strong,
}

/// Reason for generating a signal
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum SignalReason {
    /// Technical analysis based signal
    TechnicalAnalysis(String),
    /// Fundamental analysis based signal
    FundamentalAnalysis(String),
    /// Risk management triggered signal
    RiskManagement(String),
    /// Market regime change
    RegimeChange(String),
    /// Volume analysis
    VolumeAnalysis(String),
    /// Price action based
    PriceAction(String),
    /// Mean reversion signal
    MeanReversion(String),
    /// Momentum signal
    Momentum(String),
    /// Arbitrage opportunity
    Arbitrage(String),
    /// Custom reason
    Custom(String, String),
}

/// Signal metadata for additional context
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum SignalMetadata {
    /// Numeric value
    Number(f64),
    /// String value
    Text(String),
    /// Boolean value
    Boolean(bool),
    /// Timestamp value
    Timestamp(DateTime<Utc>),
    /// Price value
    Price(BigDecimal),
    /// Percentage value (0.0 to 1.0)
    Percentage(f64),
}

/// Signal validation result
#[derive(Debug)]
pub struct SignalValidation {
    pub is_valid: bool,
    pub errors: Vec<String>,
    pub warnings: Vec<String>,
}

impl Signal {
    /// Create a new signal with basic information
    pub fn new(
        id: String,
        signal_type: SignalType,
        strength: SignalStrength,
        reason: SignalReason,
    ) -> Self {
        Self {
            id,
            timestamp: Utc::now(),
            signal_type,
            strength,
            price: None,
            quantity: None,
            reason,
            metadata: HashMap::new(),
        }
    }

    /// Create a new buy signal
    pub fn buy(
        id: String,
        strength: SignalStrength,
        reason: SignalReason,
    ) -> Self {
        Self::new(id, SignalType::Buy, strength, reason)
    }

    /// Create a new sell signal
    pub fn sell(
        id: String,
        strength: SignalStrength,
        reason: SignalReason,
    ) -> Self {
        Self::new(id, SignalType::Sell, strength, reason)
    }

    /// Create a new hold signal
    pub fn hold(
        id: String,
        reason: SignalReason,
    ) -> Self {
        Self::new(id, SignalType::Hold, SignalStrength::Medium, reason)
    }

    /// Create a new close signal
    pub fn close(
        id: String,
        strength: SignalStrength,
        reason: SignalReason,
    ) -> Self {
        Self::new(id, SignalType::Close, strength, reason)
    }

    /// Set the suggested price for this signal
    pub fn with_price(mut self, price: BigDecimal) -> Self {
        self.price = Some(price);
        self
    }

    /// Set the suggested quantity for this signal
    pub fn with_quantity(mut self, quantity: BigDecimal) -> Self {
        self.quantity = Some(quantity);
        self
    }

    /// Add metadata to the signal
    pub fn with_metadata(mut self, key: String, value: SignalMetadata) -> Self {
        self.metadata.insert(key, value);
        self
    }

    /// Set custom timestamp (useful for backtesting)
    pub fn with_timestamp(mut self, timestamp: DateTime<Utc>) -> Self {
        self.timestamp = timestamp;
        self
    }

    /// Check if this is an entry signal (Buy/Sell)
    pub fn is_entry_signal(&self) -> bool {
        matches!(self.signal_type, SignalType::Buy | SignalType::Sell)
    }

    /// Check if this is an exit signal (Close/StopLoss/TakeProfit)
    pub fn is_exit_signal(&self) -> bool {
        matches!(
            self.signal_type,
            SignalType::Close | SignalType::StopLoss | SignalType::TakeProfit
        )
    }

    /// Check if this is a scaling signal (ScaleIn/ScaleOut)
    pub fn is_scaling_signal(&self) -> bool {
        matches!(
            self.signal_type,
            SignalType::ScaleIn | SignalType::ScaleOut
        )
    }

    /// Get signal strength as a numeric value (0.0 to 1.0)
    pub fn strength_value(&self) -> f64 {
        match self.strength {
            SignalStrength::Weak => 0.33,
            SignalStrength::Medium => 0.66,
            SignalStrength::Strong => 1.0,
        }
    }

    /// Validate the signal for completeness and consistency
    pub fn validate(&self) -> SignalValidation {
        let mut errors = Vec::new();
        let mut warnings = Vec::new();

        // Check for required fields
        if self.id.is_empty() {
            errors.push("Signal ID cannot be empty".to_string());
        }

        // Validate price and quantity for entry signals
        if self.is_entry_signal() {
            if self.price.is_none() {
                warnings.push("Entry signal without suggested price".to_string());
            }
            if self.quantity.is_none() {
                warnings.push("Entry signal without suggested quantity".to_string());
            }
        }

        // Validate price is positive if provided
        if let Some(ref price) = self.price {
            if price <= &BigDecimal::from(0) {
                errors.push("Signal price must be positive".to_string());
            }
        }

        // Validate quantity is positive if provided
        if let Some(ref quantity) = self.quantity {
            if quantity <= &BigDecimal::from(0) {
                errors.push("Signal quantity must be positive".to_string());
            }
        }

        // Check timestamp is not in the future (with some tolerance)
        let now = Utc::now();
        if self.timestamp > now + chrono::Duration::seconds(10) {
            warnings.push("Signal timestamp is in the future".to_string());
        }

        SignalValidation {
            is_valid: errors.is_empty(),
            errors,
            warnings,
        }
    }
}

impl SignalReason {
    /// Get a human-readable description of the signal reason
    pub fn description(&self) -> String {
        match self {
            SignalReason::TechnicalAnalysis(desc) => format!("Technical Analysis: {}", desc),
            SignalReason::FundamentalAnalysis(desc) => format!("Fundamental Analysis: {}", desc),
            SignalReason::RiskManagement(desc) => format!("Risk Management: {}", desc),
            SignalReason::RegimeChange(desc) => format!("Regime Change: {}", desc),
            SignalReason::VolumeAnalysis(desc) => format!("Volume Analysis: {}", desc),
            SignalReason::PriceAction(desc) => format!("Price Action: {}", desc),
            SignalReason::MeanReversion(desc) => format!("Mean Reversion: {}", desc),
            SignalReason::Momentum(desc) => format!("Momentum: {}", desc),
            SignalReason::Arbitrage(desc) => format!("Arbitrage: {}", desc),
            SignalReason::Custom(category, desc) => format!("{}: {}", category, desc),
        }
    }
}

impl SignalMetadata {
    /// Get the metadata value as a float if possible
    pub fn as_float(&self) -> Option<f64> {
        match self {
            SignalMetadata::Number(n) => Some(*n),
            SignalMetadata::Percentage(p) => Some(*p),
            SignalMetadata::Boolean(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => None,
        }
    }

    /// Get the metadata value as a string
    pub fn as_string(&self) -> String {
        match self {
            SignalMetadata::Number(n) => n.to_string(),
            SignalMetadata::Text(s) => s.clone(),
            SignalMetadata::Boolean(b) => b.to_string(),
            SignalMetadata::Timestamp(ts) => ts.to_rfc3339(),
            SignalMetadata::Price(p) => p.to_string(),
            SignalMetadata::Percentage(p) => format!("{:.2}%", p * 100.0),
        }
    }
}

/// Signal builder for convenient signal construction
pub struct SignalBuilder {
    id: String,
    signal_type: SignalType,
    strength: SignalStrength,
    reason: SignalReason,
    price: Option<BigDecimal>,
    quantity: Option<BigDecimal>,
    timestamp: Option<DateTime<Utc>>,
    metadata: HashMap<String, SignalMetadata>,
}

impl SignalBuilder {
    /// Create a new signal builder
    pub fn new(id: String, signal_type: SignalType) -> Self {
        Self {
            id,
            signal_type,
            strength: SignalStrength::Medium,
            reason: SignalReason::Custom("Strategy".to_string(), "Default reason".to_string()),
            price: None,
            quantity: None,
            timestamp: None,
            metadata: HashMap::new(),
        }
    }

    /// Set signal strength
    pub fn strength(mut self, strength: SignalStrength) -> Self {
        self.strength = strength;
        self
    }

    /// Set signal reason
    pub fn reason(mut self, reason: SignalReason) -> Self {
        self.reason = reason;
        self
    }

    /// Set suggested price
    pub fn price(mut self, price: BigDecimal) -> Self {
        self.price = Some(price);
        self
    }

    /// Set suggested quantity
    pub fn quantity(mut self, quantity: BigDecimal) -> Self {
        self.quantity = Some(quantity);
        self
    }

    /// Set custom timestamp
    pub fn timestamp(mut self, timestamp: DateTime<Utc>) -> Self {
        self.timestamp = Some(timestamp);
        self
    }

    /// Add metadata
    pub fn metadata(mut self, key: String, value: SignalMetadata) -> Self {
        self.metadata.insert(key, value);
        self
    }

    /// Build the signal
    pub fn build(self) -> Signal {
        Signal {
            id: self.id,
            timestamp: self.timestamp.unwrap_or_else(Utc::now),
            signal_type: self.signal_type,
            strength: self.strength,
            price: self.price,
            quantity: self.quantity,
            reason: self.reason,
            metadata: self.metadata,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_signal_creation() {
        let signal = Signal::buy(
            "test_signal".to_string(),
            SignalStrength::Strong,
            SignalReason::TechnicalAnalysis("Moving average crossover".to_string()),
        );

        assert_eq!(signal.signal_type, SignalType::Buy);
        assert_eq!(signal.strength, SignalStrength::Strong);
        assert!(signal.is_entry_signal());
        assert!(!signal.is_exit_signal());
    }

    #[test]
    fn test_signal_builder() {
        let signal = SignalBuilder::new("test".to_string(), SignalType::Sell)
            .strength(SignalStrength::Strong)
            .price(BigDecimal::from(100))
            .quantity(BigDecimal::from(10))
            .reason(SignalReason::TechnicalAnalysis("RSI oversold".to_string()))
            .metadata("rsi_value".to_string(), SignalMetadata::Number(25.0))
            .build();

        assert_eq!(signal.signal_type, SignalType::Sell);
        assert_eq!(signal.strength, SignalStrength::Strong);
        assert!(signal.price.is_some());
        assert!(signal.quantity.is_some());
        assert_eq!(signal.metadata.len(), 1);
    }

    #[test]
    fn test_signal_validation() {
        let mut signal = Signal::buy(
            "test".to_string(),
            SignalStrength::Strong,
            SignalReason::TechnicalAnalysis("Test".to_string()),
        );

        let validation = signal.validate();
        assert!(validation.is_valid);
        assert!(validation.warnings.len() >= 2); // Should warn about missing price and quantity

        // Test with invalid price
        signal.price = Some(BigDecimal::from(-100));
        let validation = signal.validate();
        assert!(!validation.is_valid);
        assert!(!validation.errors.is_empty());
    }

    #[test]
    fn test_signal_strength_value() {
        let weak_signal = Signal::new(
            "test".to_string(),
            SignalType::Buy,
            SignalStrength::Weak,
            SignalReason::TechnicalAnalysis("Test".to_string()),
        );

        assert_eq!(weak_signal.strength_value(), 0.33);

        let strong_signal = Signal::new(
            "test".to_string(),
            SignalType::Buy,
            SignalStrength::Strong,
            SignalReason::TechnicalAnalysis("Test".to_string()),
        );

        assert_eq!(strong_signal.strength_value(), 1.0);
    }

    #[test]
    fn test_signal_metadata() {
        let metadata = SignalMetadata::Number(42.5);
        assert_eq!(metadata.as_float(), Some(42.5));
        assert_eq!(metadata.as_string(), "42.5");

        let percentage = SignalMetadata::Percentage(0.15);
        assert_eq!(percentage.as_string(), "15.00%");
    }
}
